def build_middleware_stack(self) -> ASGIApp:
    debug = self.debug
    error_handler = None
    exception_handlers: dict[typing.Any, typing.Callable[[Request, Exception], Response]] = {}

    for key, value in self.exception_handlers.items():
        if key in (500, Exception):
            error_handler = value
        else:
            exception_handlers[key] = value

    middleware = (
        [Middleware(ServerErrorMiddleware, handler=error_handler, debug=debug)]
        + self.user_middleware
        + [Middleware(ExceptionMiddleware, handlers=exception_handlers, debug=debug)]
    )

    app = self.router
    for cls, args, kwargs in reversed(middleware):
        # Check if it's a class (has __init__ method) or a callable (function)
        if isinstance(cls, type):
            # It's a class, instantiate it with app as first argument
            app = cls(app, *args, **kwargs)
        else:
            # It's a callable (function), call it with app as first argument
            app = cls(app, *args, **kwargs)
    return app
